import { CUES, LINES } from "./timing";
import { VO } from "./voData";

/** 0..1 voice level for an Episode 8 line at reel frame f (0 outside the line): Rahu's mouth, Ketu's chest glow. */
export const talk8 = (line: string, f: number): number => {
  const r = LINES[line];
  const v = VO[line];
  if (!r || !v) return 0;
  const i = Math.round(f) - r[0];
  if (i < 0 || i >= v.env.length) return 0;
  const g = (k: number) => v.env[Math.max(0, Math.min(v.env.length - 1, k))];
  return Math.min(1, ((g(i - 1) + 2 * g(i) + g(i + 1)) / 4) * 1.1);
};

/** A cue frame from timing.ts (generated by scripts/manthan_ep8_audio.py). */
export const cue8 = (k: keyof typeof CUES): number => CUES[k];

/** Local progress 0..1 of frame f through [a, b). */
export const prog8 = (f: number, a: number, b: number): number => Math.max(0, Math.min(1, (f - a) / Math.max(1, b - a)));
